// Atomic batch approval with same-transaction audit and scoped idempotency.
//
// The transactional work (guarded RLS binding, scoped key lock, replay lookup,
// all-or-nothing approval, ApprovalAudit and ActionRequest inserts) is owned by
// the protected internal/action Executor. This package only adapts its values
// and errors to the shared protocol adapter.
package candidate

import (
	"context"
	"errors"
	"net/http"

	"github.com/XUJiahua/enterprise_agent/internal/action"
	"github.com/XUJiahua/enterprise_agent/internal/app"
	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5/pgxpool"
)

func New(ctx context.Context, pool *pgxpool.Pool, fallback http.Handler) (http.Handler, error) {
	// Empty mutation: no controlled faults. New also verifies the guarded
	// Purchase runtime and the append-only RLS configuration of the new tables.
	exec, err := action.New(ctx, pool, "")
	if err != nil {
		return nil, err
	}
	approve := func(ctx context.Context, u app.Identity, key string, ids []string) (protocol.Result, bool, error) {
		// u is the identity bound by the adapter from Authorization only;
		// no client-supplied context header is consulted.
		result, replayed, err := exec.BulkApprove(ctx, u, key, ids)
		if err != nil {
			var rejected *action.Rejection
			if errors.As(err, &rejected) {
				return protocol.Result{}, false, &protocol.Rejection{Status: rejected.Status}
			}
			// Database errors pass through unchanged so the adapter can map
			// unique violations (23505) to 409 and everything else to 503.
			return protocol.Result{}, false, err
		}
		approved := result.ApprovedIDs
		if approved == nil {
			approved = []string{}
		}
		return protocol.Result{ApprovedIDs: approved}, replayed, nil
	}
	return protocol.HTTP(approve, fallback), nil
}

